"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["14183"],{94524(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.regra_derivacao_configurada.contribui_em_branco","status":422,"titulo":"O c\xf3digo contribu\xeddo pela regra n\xe3o pode ficar em branco"},"descricao":{"codigo":"uniplus.selecao.regra_derivacao_configurada.contribui_em_branco","requisitos":["UNI-REQ-0075"],"oQueAconteceu":["Na defini\xe7\xe3o das regras de deriva\xe7\xe3o do processo\\n(`PUT /api/selecao/processos-seletivos/{id}/regras-derivacao`), uma regra\\ninformou `contribui` vazio ou s\xf3 com espa\xe7os. Em um fato derivado por regra, o\\nc\xf3digo contribu\xeddo \xe9 um c\xf3digo do dom\xednio do fato (UNI-REQ-0075); s\xf3 o fato\\nderivado booleano n\xe3o contribui c\xf3digo, e nele o campo \xe9 omitido. Um texto em\\nbranco n\xe3o \xe9 nem uma coisa nem outra: \xe9 um c\xf3digo mal preenchido, e o sistema n\xe3o\\no trata como derivado booleano.","A recusa vem no array `errors[]`, no campo\\n`configuracoes[<i>].regras[<j>].contribui`, e faz parte da confer\xeancia de forma,\\nque acumula todas as viola\xe7\xf5es de todas as configura\xe7\xf5es e regras do pedido\\nantes de consultar o cat\xe1logo de fatos. Quando o problema \xe9 misturar regras com\\ne sem c\xf3digo na mesma configura\xe7\xe3o, a recusa \xe9 outra\\n([`regras_com_e_sem_codigo`](/erros/uniplus.selecao.configuracao_derivacao_fato.regras_com_e_sem_codigo)).","A mesma confer\xeancia roda quando o sistema rel\xea a configura\xe7\xe3o congelada da\\nvers\xe3o publicada, nas demais opera\xe7\xf5es da lista do cabe\xe7alho. A consulta de\\nconformidade do processo tamb\xe9m rel\xea a vers\xe3o, mas converte a falha em pend\xeancia\\ndo checklist, e por isso n\xe3o consta no cabe\xe7alho. Pelo caminho normal de\\ngrava\xe7\xe3o, a configura\xe7\xe3o congelada nunca traz um c\xf3digo em branco, porque a\\ndefini\xe7\xe3o das regras o recusa antes. Nessas leituras a recusa sai como viola\xe7\xe3o\\n\xfanica, sem a lista `errors[]`, e se refere \xe0 vers\xe3o congelada, n\xe3o ao pedido\\nenviado."],"comoResolver":["Na defini\xe7\xe3o das regras, conforme a natureza do fato derivado:","- **o fato deriva um c\xf3digo do dom\xednio:** informe em `contribui` o c\xf3digo de\\n  valor do fato, sem espa\xe7os sobrando;\\n- **o fato derivado \xe9 booleano:** omita `contribui` na regra.","Envie ent\xe3o o pedido de novo.","Se o erro apareceu em uma opera\xe7\xe3o que l\xea a configura\xe7\xe3o congelada (qualquer\\numa das listadas no cabe\xe7alho, exceto a defini\xe7\xe3o das regras), o pedido enviado\\nagora n\xe3o \xe9 a causa: o defeito est\xe1 na regra de deriva\xe7\xe3o congelada na vers\xe3o\\npublicada do processo, e regravar as regras do processo n\xe3o a corrige. A causa \xe9\\ninvestigada pela equipe t\xe9cnica do Uni+."],"ondeAparece":["Defini\xe7\xe3o de regras de deriva\xe7\xe3o de fatos do processo seletivo","Retifica\xe7\xe3o em ato \xfanico","Defini\xe7\xe3o de etapas e do cronograma das fases de processo publicado, quando declaram atos","Consulta do formul\xe1rio renderiz\xe1vel do processo","Consulta do formul\xe1rio da inscri\xe7\xe3o","In\xedcio, salvamento, envio, cancelamento e descarte do rascunho da inscri\xe7\xe3o","Avalia\xe7\xe3o da inscri\xe7\xe3o","In\xedcio, confirma\xe7\xe3o e remo\xe7\xe3o de envio de documento da inscri\xe7\xe3o","Consulta e emiss\xe3o do comprovante da inscri\xe7\xe3o","Consulta administrativa da inscri\xe7\xe3o e dos documentos dela","Publica\xe7\xe3o de produto do edital e listagem de produtos previstos do processo","Notas do ENEM (importa\xe7\xe3o de lote, gera\xe7\xe3o do envio ao INEP e consulta de lotes e de envios)"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Regra derivacao configurada"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"bac0ecb24f352b6341ba53a00922b6237dd7a678"}}')}}]);